
import {
  ArgumentsHost,
  Catch,
  ExceptionFilter,
  HttpException,
  HttpStatus,
} from '@nestjs/common';
import { randomUUID } from 'node:crypto';
import type { Request, Response } from 'express';

@Catch()
export class HttpExceptionFilter implements ExceptionFilter {
  catch(exception: unknown, host: ArgumentsHost): void {
    const context = host.switchToHttp();

    const response = context.getResponse<Response>();
    const request = context.getRequest<Request & { requestId?: string }>();

    // Reuse the ID generated by middleware.
    // Generate a fallback only if middleware did not assign one.
    const requestId = request.requestId ?? randomUUID();

    response.setHeader('X-Request-Id', requestId);

    let statusCode = HttpStatus.INTERNAL_SERVER_ERROR;
    let errorCode = 'INTERNAL_SERVER_ERROR';
    let message = 'An unexpected error occurred.';
    let details: string[] = [];

    if (exception instanceof HttpException) {
      statusCode = exception.getStatus();

      const exceptionResponse = exception.getResponse();

      let exceptionMessages: string | string[] | undefined;

      if (
        typeof exceptionResponse === 'object' &&
        exceptionResponse !== null &&
        'message' in exceptionResponse
      ) {
        const responseMessage = exceptionResponse.message;

        if (
          typeof responseMessage === 'string' ||
          Array.isArray(responseMessage)
        ) {
          exceptionMessages = responseMessage as string | string[];
        }
      } else if (typeof exceptionResponse === 'string') {
        exceptionMessages = exceptionResponse;
      }

      // ValidationPipe returns an array of validation messages.
      const isValidationError =
        statusCode === HttpStatus.BAD_REQUEST &&
        Array.isArray(exceptionMessages);

      if (isValidationError && Array.isArray(exceptionMessages)) {
        errorCode = 'VALIDATION_FAILED';
        message = 'The request could not be validated.';
        details = exceptionMessages;
      } else {
        // Map HTTP status codes to stable API error codes.
        switch (statusCode) {
          case HttpStatus.BAD_REQUEST:
            errorCode = 'BAD_REQUEST';
            message = 'The request is invalid.';
            break;

          case HttpStatus.UNAUTHORIZED:
            errorCode = 'UNAUTHORIZED';
            message = 'Authentication is required.';
            break;

          case HttpStatus.FORBIDDEN:
            errorCode = 'FORBIDDEN';
            message = 'You do not have permission to perform this action.';
            break;

          case HttpStatus.NOT_FOUND:
            errorCode = 'RESOURCE_NOT_FOUND';
            message = 'The requested resource was not found.';
            break;

          case HttpStatus.CONFLICT:
            errorCode = 'CONFLICT';
            message = 'The request conflicts with the current state.';
            break;

          case HttpStatus.TOO_MANY_REQUESTS:
            errorCode = 'TOO_MANY_REQUESTS';
            message = 'Too many requests. Please try again later.';
            break;

          default:
            if (statusCode >= 500) {
              errorCode = 'INTERNAL_SERVER_ERROR';
              message = 'An unexpected error occurred.';
            } else {
              errorCode = 'HTTP_ERROR';
              message = 'The request could not be completed.';
            }
        }
      }
    }

    // Return a consistent response without exposing internal exceptions.
    response.status(statusCode).json({
      error: {
        code: errorCode,
        message,
        details,
        requestId,
      },
    });
  }
}
